insert into public.norme (id, norma_id, titolo, estremi, descrizione, articoli_chiave, tags, url_normattiva, url_ricerca, convenzione_only, testo_vigente, testo_vigente_at, embedding, creato_il, aggiornato_il) values ('081159e7-4d44-49ac-bf6f-c81c296211e1', 'd_lgs_163_2006', 'Misure di sicurezza per le reti e i sistemi informativi della Pubblica Amministrazione', 'Decreto Legislativo 7 marzo 2006, n. 163', 'Stabilisce le misure minime di sicurezza da adottare per proteggere le reti e i sistemi informativi della PA, includendo disposizioni specifiche per l’utilizzo di servizi cloud. È pertinente perché l’adozione di risorse GCP deve rispettare gli standard di sicurezza previsti dalla normativa nazionale.', ARRAY['art. 2 — obblighi di sicurezza per le PA: impone l’adozione di misure tecniche e organizzative adeguate', 'art. 4 — valutazione del rischio: richiede l’analisi dei rischi connessi all’uso di servizi cloud', 'art. 6 — certificazioni e standard: prevede l’adozione di standard riconosciuti (ISO/IEC 27001, etc.) per i fornitori cloud']::text[], ARRAY['sicurezza informatica', 'cloud', 'GCP', 'normativa ICT', 'valutazione rischio', 'certificazioni', 'protezione dati', 'PA']::text[], 'https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2006-03-07;163', '', false, '', NULL, '[-0.030059252,-0.015050964,0.024849407,-0.042738426,-0.004893633,0.012289313,0.03496067,0.028515493,-0.023105146,0.01953369,-0.005532402,-0.056022722,0.047123708,0.007956397,-0.03388873,-0.022211386,0.042283837,0.02832456,-0.02829405,0.047292173,0.08160956,-0.015019341,-0.04170594,-0.012439013,0.005056606,0.06365615,-0.042455938,-0.058069654,-0.034079302,-0.22497168,-0.026353084,-0.061934393,0.07641418,-0.05625965,-0.016473357,-0.027761834,-0.015055306,0.028127756,-0.024587698,0.035269573,-0.0057141148,-0.046067595,-0.029444017,-0.043739934,-0.00675864,-0.053513985,-0.03777994,0.021826277,-0.03245811,-0.0047363034,-0.020195862,0.020801296,0.00925929,0.052141428,0.00270811,0.