insert into public.norme (id, norma_id, titolo, estremi, descrizione, articoli_chiave, tags, url_normattiva, url_ricerca, convenzione_only, testo_vigente, testo_vigente_at, embedding, creato_il, aggiornato_il) values ('9f43ffef-65ac-47a1-b666-390324a65290', 'd_lgs_196_2003', 'Codice in materia di protezione dei dati personali', 'Decreto Legislativo 30 giugno 2003, n. 196 (modificato dal D.Lgs. 101/2018 – adeguamento al GDPR)', 'Regola il trattamento dei dati personali, includendo le disposizioni relative al trasferimento e alla conservazione dei dati su piattaforme cloud. È rilevante per la gestione di risorse GCP poiché la PA deve assicurare la conformità al trattamento dei dati sensibili e alle norme sulla privacy.', ARRAY['art. 33 — misure di sicurezza per il trattamento dei dati: obbliga l’adozione di misure adeguate anche in ambiente cloud', 'art. 35 — valutazione d''impatto sulla protezione dei dati (DPIA): necessaria per l’uso di servizi cloud che trattano dati personali', 'art. 44 — trasferimento di dati all’estero: disciplina le condizioni per l’utilizzo di data center situati fuori dall’UE']::text[], ARRAY['privacy', 'GDPR', 'dati personali', 'cloud', 'GCP', 'sicurezza', 'PA', 'trattamento dati']::text[], 'https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2003-06-30;196', '', false, '', NULL, '[-0.02025304,-0.026267832,0.023977114,-0.0699918,0.0024452042,0.010153966,0.071817316,0.01643319,0.0070613585,-0.033926476,-0.016126154,-0.04500648,0.035722967,0.03052367,-0.0120108565,-0.017257543,-0.0065765586,0.03304698,-0.051245503,0.032457814,0.079218425,-0.052498244,-0.06784114,-0.046129927,-0.02578643,0.08193469,-0.05755962,-0.037637044,-0.01612474,-0.20565721,-0.013848565,-0.031509902,0.080589995,-0.03854073,-0.0060882783,-0.05272681,-0.026578624,0.026650066,0.0034151163,0.03239289,-0.0073376005,-0.031684246,-0.0255864,-0.031933874,-0.016910395,-0.020241143,-0.016135335,0.017305994,-0.05913464,-0.0106243845,0.00036708906,0.04198981,-0.0