insert into public.norme (id, norma_id, titolo, estremi, descrizione, articoli_chiave, tags, url_normattiva, url_ricerca, convenzione_only, testo_vigente, testo_vigente_at, embedding, creato_il, aggiornato_il) values ('b6393251-221c-4269-9f0f-943f31bbeee5', 'd_lgs_33_2013', 'Riordino della disciplina della trasparenza e dell’accesso alle informazioni pubbliche', 'D.Lgs. 14 marzo 2013, n. 33', 'Stabilisce gli obblighi di trasparenza, pubblicità e accesso alle informazioni relative alle attività della pubblica amministrazione, inclusi gli appalti. È pertinente per l’acquisto di notebook perché impone la pubblicazione di atti, avvisi e risultati di gara, garantendo la tracciabilità e la partecipazione dei soggetti interessati.', ARRAY['art. 1 — principio di trasparenza', 'art. 5 — pubblicità degli atti amministrativi', 'art. 7 — obblighi di pubblicazione dei dati di gara', 'art. 13 — accesso civico e diritto di accesso alle informazioni']::text[], ARRAY['trasparenza', 'pubblicità_gare', 'accesso_informazioni', 'amministrazione_pubblica', 'procurement', 'notebook', 'acquisti_pubblici', 'open_data']::text[], 'https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legge:2013-03-14;33', '', false, '', NULL, '[-0.02800243,0.01485392,0.021679277,0.0022066217,-0.0025907266,0.010682134,0.022584775,0.05291496,0.032398727,-0.019389132,-0.07205396,-0.011195735,0.03795912,0.036591023,-0.009804515,-0.031680588,0.01648154,0.017317379,0.018651988,0.0522843,0.05805691,-0.06562918,0.0032616807,-0.034351356,0.022825642,0.060602758,-0.092375875,-0.033905666,-0.057708655,-0.20796335,-0.0303054,-0.044241887,0.06544927,-0.041470908,0.0120531125,-0.0008965197,-0.008578876,0.0700048,0.042763684,0.023277268,0.000488784,-0.0032089665,-0.027215429,-0.06374641,-0.018795945,-0.03413348,-0.030468185,0.026762007,-0.019546567,-0.012343317,-0.020085875,0.035879217,0.013894261,0.055944785,-0.021564886,0.052892905,0.026893629,0.028200144,0.035504866,0.05712456,0.04976885,0.082769394,-0.26090437,0.