insert into public.norme (id, norma_id, titolo, estremi, descrizione, articoli_chiave, tags, url_normattiva, url_ricerca, convenzione_only, testo_vigente, testo_vigente_at, embedding, creato_il, aggiornato_il) values ('4fb8e474-e681-4e20-9b6c-d8c26587f5f0', 'dlgs_30_2018', 'D.Lgs. 101/2018 - Attuazione della direttiva (UE) 2016/680 del Parlamento europeo e del Consiglio, del 27 aprile 2016, relativa alla protezione delle persone fisiche con riguardo al trattamento dei dati personali da parte delle autorità competenti a fini di prevenzione, indagine, accertamento e perseguimento di reati o esecuzione di sanzioni penali, nonché alla libera circolazione di tali dati', 'D.Lgs. 30 agosto 2018, n. 101', 'Il D.Lgs. 101/2018 disciplina il trattamento dei dati personali da parte delle autorità competenti a fini di prevenzione, indagine, accertamento e perseguimento di reati o esecuzione di sanzioni penali. È rilevante per la query in quanto disciplina l''utilizzo dei dati personali nel contesto della protezione dei dati.', ARRAY['Art. 4 - Principi del trattamento', 'Art. 5 - Trattamento dei dati personali', 'Art. 10 - Diritti dell''interessato']::text[], ARRAY['protezione dei dati', 'trattamento dei dati personali', 'autorità competenti', 'prevenzione', 'indagine', 'accertamento', 'perseguimento di reati']::text[], 'https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2018-08-30;101', 'https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2018-08-30;101', false, '', NULL, '[-0.050841466,-0.0060215215,0.011629078,-0.0330293,0.00046430106,-0.012310164,0.07111082,0.044611428,0.009175668,-0.031489722,-0.023548096,-0.040004615,0.014697986,0.06290861,-0.021784304,-0.023539474,-0.007505423,0.054817352,-7.8729565e-05,0.05272393,0.077135175,-0.03032047,-0.03922668,-0.078605376,-0.002166635,0.053260528,-0.053715035,-0.03819077,-0.01777131,-0.21178123,0.025965108,-0.0141873425,0.01485123,-0.043806504,-0.0015151706,-0.023458218,-0.034027707,0.05659