insert into public.norme (id, norma_id, titolo, estremi, descrizione, articoli_chiave, tags, url_normattiva, url_ricerca, convenzione_only, testo_vigente, testo_vigente_at, embedding, creato_il, aggiornato_il) values ('b8baceb1-bf59-4ff0-a06c-1120a657e502', 'dpr_30_2005', 'Regolamento per la valutazione della non autosufficienza delle persone anziane', 'Decreto del Presidente della Repubblica 30 aprile 2005, n. 139', 'Il D.P.R. 139/2005 disciplina i criteri, le modalità e le procedure per la valutazione della non autosufficienza delle persone anziane, nonché la redazione del relativo certificato di non autosufficienza. È fondamentale per l’individuazione dei soggetti aventi diritto all’assistenza sociale e per la determinazione della quota di compartecipazione alla spesa basata sull’ISEE.', ARRAY['art. 1 — Ambito di applicazione e soggetti destinatari', 'art. 2 — Criteri di valutazione della non autosufficienza (gruppi di bisogni, punteggi, soglie)', 'art. 3 — Procedura di accertamento e ruolo degli operatori sanitari e sociali', 'art. 4 — Rilascio del certificato di non autosufficienza e validità temporale', 'art. 5 — Rapporti con le amministrazioni locali e utilizzo del certificato ai fini della compartecipazione alla spesa']::text[], ARRAY['assistenzanziani', 'nonautosufficienza', 'valutazione', 'servizisociali', 'certificato', 'ise', 'condividecipazione', 'dpr', 'normativa', 'salute']::text[], 'https://www.normattiva.it/uri-res/N2Ls?urn:nir:presidente.repubblica:decreto:2005-04-30;139', 'https://www.normattiva.it/uri-res/N2Ls?urn:nir:presidente.repubblica:decreto:2005-04-30;139', false, '', NULL, '[-0.03996254,0.03459981,0.045702804,-0.030681174,-0.029758058,0.015335284,0.06892121,0.03474304,-0.011447539,-0.010702556,-0.0022283976,-0.030925788,0.02964152,0.051642414,-0.017086742,-0.03098546,-0.0028748934,0.082965985,0.005112376,0.024097273,0.06898649,-0.0406907,-0.027092138,-0.024356196,0.05579483,0.04634912,-0.02099982,-0.078611836,-0.017925028,-0.18224344,0.00